<template>
  <div class="container page-height-limit">
    <div class="full-width">
      <q-list bordered class="rounded-borders" v-if="data_types_loaded">
        <template
          v-for="(type, index) in data_types"
          :key="index"
          :props="props"
          ><q-separator />
          <q-expansion-item
            expand-separator
            header-class="highlighted-back"
            :default-opened="index == 0 ? true : false"
          >
            <template v-slot:header>
              <q-icon
                size="25px"
                class="q-mr-lg black_to_white"
                name="store"
              />
              <span style="margin-top: 3px; text-transform: capitalize">
                {{ $t(aliases[type] || type) }}</span
              >
              <q-space />
            </template>
            <q-card>
              <q-card-section :style="'height: auto; min-height: 15vh;'">
                <MasterDataTypeList :type_name="type" />
              </q-card-section>
            </q-card>
          </q-expansion-item>
          <q-separator />
        </template>
      </q-list>
    </div>
  </div>

  <q-dialog v-model="show_custom_master_data">
    <CustomMasterDataPopUp />
  </q-dialog>

  <!-- <q-inner-loading :showing="loading" style="z-index: 2;">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading> -->
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { custom_master_data } from 'src/constants';
import { useMasterDataLookupStore, useSettingStore } from 'src/store/main';
import MasterDataTypeList from 'src/pages/Settings/Components/MasterDataLookup/MasterDataTypeList.vue';
import CustomMasterDataPopUp from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/listPopUp.vue';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {},
  components: {
    CustomMasterDataPopUp,
    MasterDataTypeList,
  },
  data() {
    return {
      tab: ref('tables'),
      custom_master_data,
    };
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    const master_data_lookup_store = useMasterDataLookupStore();
    master_data_lookup_store.$reset();
    next();
  },
  setup() {
    const master_data_lookup_store = useMasterDataLookupStore();
    const { getDataSetTypes, getDataSetAliases, getMasterDataList } =
      master_data_lookup_store;
    const { aliases, data_types, data_types_loaded } = storeToRefs(
      master_data_lookup_store,
    );

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;
    return {
      user_settings,

      data_types_loaded,
      startSettingsFetch,
      getDataSetTypes,
      getDataSetAliases,
      getMasterDataList,
      aliases,
      data_types,
      loading: ref(false),
      show_custom_master_data: ref(false),
    };
  },

  mounted: function () {
    this.initView();
  },
  methods: {
    async initView() {
      try {
        // this.loading = true;
        await this.getDataSetTypes();
        await this.getDataSetAliases();
        await this.startSettingsFetch();
        await this.getMasterDataList('record');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.loading = false;
      }
    },
  },
});
</script>
